sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var gate = new x_ssa_day2_ops.EntraHelpdeskGate();
  var verdict = gate.verify({
    action: 'disableUser',
    userId: 'test-user-0001',
    observed: { accountEnabled: true },   // contradicts the intent
    intended: { accountEnabled: false }
  });
  if (verdict && verdict.ok) {
    stepResult.setFailed('verify reported ok while observed state contradicted intent');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
